sys_script_include.script:
var EquipmentUtils = Class.create();
EquipmentUtils.prototype = {
    initialize: function() {
    },

    hasExceededRequestLimit: function(userId, maxLimit) {
        if (!userId) return false;
        if (!maxLimit) maxLimit = 3;

        var reqGr = new GlideRecord('x_2266883_employ_0_equipment_request');
        reqGr.addQuery('requested_for', userId);
        // ค้นหาเฉพาะสถานะที่ยังไม่จบ (1=Draft, 2=Submitted, 3=Approved)
        reqGr.addQuery('state', 'IN', '1,2,3');
        reqGr.query();

        var pendingCount = reqGr.getRowCount();
        gs.info('[EquipmentUtils] User ' + userId + ' has ' + pendingCount + ' active requests.');

        return pendingCount >= maxLimit;
    },

    type: 'EquipmentUtils'
};
